"""天气数据聚合。本模块的返回结构是权威定义，不要修改本文件。"""


def daily_range(temperatures):
    """返回 {"low": 最低温, "high": 最高温}；空输入返回 None。"""
    if not temperatures:
        return None
    return {"low": min(temperatures), "high": max(temperatures)}


def average(temperatures):
    """返回平均温度；空输入返回 None。"""
    if not temperatures:
        return None
    return sum(temperatures) / len(temperatures)

"""一周天气简报：调用 weather 模块生成每日低温/高温/均值。"""

from weather import average, daily_range

WEEK = {
    "周一": [18, 26],
    "周二": [17, 25],
    "周三": [20, 29],
}


def briefing():
    lines = []
    for day, temps in WEEK.items():
        spread = daily_range(temps)
        lines.append(
            f"{day} 最低 {spread['min']} 最高 {spread['max']} 平均 {average(temps):.1f}"
        )
    return "\n".join(lines)


if __name__ == "__main__":
    print(briefing())
